{
  "title": "干爽的插头",
  "synopsis": "老街广播站突发断电，林岚排查发现设备并未进水，用干爽的插头戳穿了周野的谎言，逼迫他面对逃避告别的内心恐惧。",
  "preview_blurb": "老街广播站突发断电，维修员排查却发现插头干爽。当告别的时刻被强行拖延，谁在害怕说出那句再见？",
  "scenes": [
    {
      "title": "戳穿谎言",
      "location": "广播站调音台前",
      "dramatic_goal": "林岚合上主闸刀，用万用表和干爽的插头直接戳穿设备进水短路的谎言，证明是人为物理断电。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "主闸合上，变压器嗡嗡声正常。万用表测主线，阻值稳定，没有任何短路痕迹。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "那怎么没声？肯定是墙里暗线老化，或者昨天暴雨顺着缝隙进水了！这老房子就这样，修不好的。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "进水？你看这插头。金属片干爽，连一滴水渍都没有。侧面还有你大拇指用力按压留下的防滑纹。周野，这是人为物理断电。"
        },
        {
          "kind": "narration",
          "text": "插头被拔出的摩擦声，在安静的广播站里格外清晰。"
        }
      ]
    },
    {
      "title": "逃避与直面",
      "location": "广播站调音台前",
      "dramatic_goal": "周野防线崩溃坦白逃避告别的原因，林岚重新插紧电源，用理解与陪伴打破他的心理防线。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "我……是我拔的。明天老街就要拆了，这是最后一期节目。我不敢对着麦克风说那句再见。我想着要是设备坏了，是不是就能多拖几天……"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "逃避不会让告别消失。你拔掉电源，只会让老街坊们连最后的声音都听不到。他们在收音机前等了一早上，不是为了听哑巴广播的。"
        },
        {
          "kind": "narration",
          "text": "插头被重新用力插紧，设备指示灯再次亮起，微弱的电流底噪重新填满房间。"
        }
      ]
    },
    {
      "title": "按下去的力量",
      "location": "广播站麦克风前",
      "dramatic_goal": "林岚推上推子亮起ON AIR灯，在周野手抖无法按键时，覆上他的手背给予力量。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "主推子我推上去了，ON AIR灯亮了。坐在麦克风前，把欠大家的告别好好说完。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "我手抖得厉害……我真的按不下去。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别怕，我陪你。按吧。"
        },
        {
          "kind": "narration",
          "text": "两只手叠在一起，播音键发出一声清脆的咔哒声。"
        }
      ]
    }
  ],
  "episode_summary": "林岚通过万用表和干爽的插头戳穿了周野人为断电的谎言。周野坦白因害怕老街拆迁的告别而逃避，林岚没有责备，而是重新接通电源，陪伴他面对麦克风，给了他按下播音键的力量。",
  "ending_hook": "",
  "fact_delta": [
    {
      "change": "确认广播站断电原因是周野因害怕告别而人为拔掉电源，设备并未进水。"
    }
  ],
  "relationship_delta": [
    {
      "change": "两人从隐瞒与揭穿的对立，走向理解与陪伴，林岚用默默的支持推了周野一把。"
    }
  ],
  "new_open_threads": [
    "周野能否顺利完成最后一次告别广播",
    "广播站设备的最终去向与两人的未来约定"
  ],
  "closed_threads": []
}
